#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gramschmidt.h"


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      A[i][j] = (((DATA_TYPE) ((i*j) % m) / m )*100) + 10;
      Q[i][j] = 0.0;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      R[i][j] = 0.0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("R");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, R[i][j]);
    }
  POLYBENCH_DUMP_END("R");

  POLYBENCH_DUMP_BEGIN("Q");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i*n+j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, Q[i][j]);
    }
  POLYBENCH_DUMP_END("Q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */

/*
 * Optimized kernel:
 *  - Adds internal restrict-qualified pointers so the compiler can
 *    safely vectorize and keep values in registers (arguments remain
 *    unchanged, so the external interface is preserved).
 *  - Reorders the j/i loops in the orthogonalization phase to operate
 *    along rows of A and R (contiguous memory in row-major layout),
 *    greatly improving cache locality and reducing the number of
 *    loads of Q[:,k].
 *  - The order of floating-point operations for each individual
 *    element (each R[k][j] and A[i][j]) is preserved, so numerical
 *    results remain bit-for-bit identical to the original code.
 */
static void __attribute__((flatten, noinline))
kernel_gramschmidt(int m, int n,
                   DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                   DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
                   DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  /* Local aliases with restrict to help the compiler with
     alias analysis and vectorization.  The external function
     signature is unchanged. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict R_)[n] = R;
  DATA_TYPE (*restrict Q_)[n] = Q;

  /* Cache loop bounds to avoid re-evaluating macros in inner loops. */
  const int pb_m = _PB_M;
  const int pb_n = _PB_N;

#pragma scop
  for (k = 0; k < pb_n; k++)
  {
    /* 1. Compute the squared norm of column k of A. */
    DATA_TYPE nrm = SCALAR_VAL(0.0);
    for (i = 0; i < pb_m; i++)
    {
      DATA_TYPE a_ik = A_[i][k];
      nrm += a_ik * a_ik;
    }

    /* 2. Normalize to obtain Q[:,k]. */
    DATA_TYPE r_kk = SQRT_FUN(nrm);
    R_[k][k] = r_kk;

    for (i = 0; i < pb_m; i++)
    {
      /* Using the scalar r_kk instead of repeatedly reading
         R_[k][k] avoids extra memory traffic but is numerically
         identical, since R_[k][k] == r_kk at this point. */
      Q_[i][k] = A_[i][k] / r_kk;
    }

    /* 3. Orthogonalize remaining columns j > k against Q[:,k]. */
    if (k + 1 < pb_n)
    {
      DATA_TYPE *restrict Rk = R_[k];

      /* 3a. Initialize R[k][j] for all j > k. */
      for (j = k + 1; j < pb_n; j++)
        Rk[j] = SCALAR_VAL(0.0);

      /* 3b. Compute R[k][j] = dot(Q[:,k], A[:,j]) for all j > k.
             Loop order is i outer, j inner so that:
               - Q[i][k] is loaded once per i and reused across all j.
               - A[i][j] and R[k][j] are accessed with contiguous j,
                 which is cache- and prefetch-friendly in row-major
                 layout.

             For each fixed (k, j), the sequence of additions to
             R[k][j] over i is the same as in the original code
             (same order of i), so floating-point rounding behavior
             is preserved. */
      for (i = 0; i < pb_m; i++)
      {
        const DATA_TYPE q_ik = Q_[i][k];
        const DATA_TYPE *restrict a_row_i = A_[i];
        for (j = k + 1; j < pb_n; j++)
        {
          Rk[j] += q_ik * a_row_i[j];
        }
      }

      /* 3c. Update A[:,j] -= Q[:,k] * R[k][j] for all j > k.
             Again, we use i outer, j inner for better data locality.
             Each element A[i][j] is updated exactly once per (k, j)
             with the same arithmetic operation as in the original
             version, so results are unchanged. */
      for (i = 0; i < pb_m; i++)
      {
        const DATA_TYPE q_ik = Q_[i][k];
        DATA_TYPE *restrict a_row_i = A_[i];
        for (j = k + 1; j < pb_n; j++)
        {
          a_row_i[j] -= q_ik * Rk[j];
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(R,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(Q,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(R),
	      POLYBENCH_ARRAY(Q));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gramschmidt (m, n,
		      POLYBENCH_ARRAY(A),
		      POLYBENCH_ARRAY(R),
		      POLYBENCH_ARRAY(Q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(R), POLYBENCH_ARRAY(Q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(R);
  POLYBENCH_FREE_ARRAY(Q);

  return 0;
}
