/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/ */

/*  Optimization notes
 *  -------------------
 *  - We create local restrict-qualified aliases A_, R_, Q_ to help the
 *    compiler assume no aliasing between the main arrays.
 *  - We introduce a temporary contiguous buffer q_col[m] that caches the
 *    current column Q[:,k]. This avoids repeatedly reading Q[:,k] with
 *    a large stride in the innermost loops, improving cache use and
 *    vectorization while keeping the mathematical operations and their
 *    order unchanged.
 *  - The j-loop (over columns j>k) is parallelized with OpenMP. Each
 *    iteration operates on an independent column (distinct R[k][j] and
 *    A[:,j]), so this does not change the computation order within each
 *    column and thus preserves numerical semantics.
 */
static void __attribute__((flatten, noinline))
kernel_gramschmidt(int m, int n,
                   DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                   DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
                   DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;

  DATA_TYPE nrm;

  /* Local restrict-qualified aliases improve optimization by
     telling the compiler these 2D arrays do not alias. */
  DATA_TYPE (* restrict A_)[n] = A;
  DATA_TYPE (* restrict R_)[n] = R;
  DATA_TYPE (* restrict Q_)[n] = Q;

  /* Contiguous cache of the current Q column:
     q_col[i] == Q_[i][k] for the active k.
     Size m is equal to the number of rows (_PB_M). */
  DATA_TYPE q_col[m];

#pragma scop
  for (k = 0; k < _PB_N; k++)
  {
    /* Compute the Euclidean norm of column k of A. */
    nrm = SCALAR_VAL(0.0);
    for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE Aik = A_[i][k];
      nrm += Aik * Aik;
    }

    R_[k][k] = SQRT_FUN(nrm);

    /* Normalize column k of A into Q, and cache it into q_col.
       This preserves the original operation order and arithmetic:
         Q[i][k] = A[i][k] / R[k][k]
     */
    for (i = 0; i < _PB_M; i++)
    {
      DATA_TYPE q = A_[i][k] / R_[k][k];
      Q_[i][k]   = q;
      q_col[i]   = q;
    }

    /* Orthogonalize remaining columns against Q[:,k].
       Each column j>k is independent, so we parallelize across j.
       Inside each j-iteration, the computation proceeds in the same
       order as the original code (i is still the innermost loop). */
#pragma omp parallel for private(i) schedule(static)
    for (j = k + 1; j < _PB_N; j++)
    {
      DATA_TYPE rkj = SCALAR_VAL(0.0);

      /* Compute R[k][j] = dot(Q[:,k], A[:,j]).
         Using q_col avoids strided reads from Q_. */
      for (i = 0; i < _PB_M; i++)
        rkj += q_col[i] * A_[i][j];

      R_[k][j] = rkj;

      /* Update column j of A:
           A[:,j] <- A[:,j] - Q[:,k] * R[k][j]
         Again use q_col for better locality. */
      for (i = 0; i < _PB_M; i++)
        A_[i][j] -= q_col[i] * rkj;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
