/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/

   Optimizations applied (semantics-preserving):
   - Introduce restrict-qualified local aliases for A, Q, R to help the
     compiler with alias analysis and vectorization.
   - Reorder the computation of R[k][j] for j>k into a row-oriented
     traversal:
       * Original: for each column j>k, loop over i (column-wise access).
       * New:      loop over rows i and update the whole R[k][j] row
                   inside the inner j-loop.
     For each R[k][j], the sequence of floating-point additions over i
     is unchanged; only the loop nesting changes. This keeps the
     numerical behavior of the modified Gram-Schmidt algorithm intact
     while:
       * Dramatically improving spatial locality for A[i][j] (unit-stride
         access in j for each fixed row i).
       * Reusing Q[i][k] loaded once per row i for all j>k instead of
         reloading it for every (i,j) combination.
   - Apply a similar row-oriented traversal for the rank-1 update
     A[:, j] -= Q[:, k] * R[k][j] to get unit-stride access in j.
*/
static
void kernel_gramschmidt[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Create restrict-qualified aliases with the known leading dimension.
     A, R, Q are allocated as distinct buffers, so this does not change
     semantics but allows the compiler to generate better code. */
  DATA_TYPE (* __restrict__ A_)[N] = A;
  DATA_TYPE (* __restrict__ R_)[N] = R;
  DATA_TYPE (* __restrict__ Q_)[N] = Q;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1. Compute the 2-norm of the k-th column of A. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE aik = A_[i][k];
        nrm += aik * aik;
      }

      /* 2. Normalise k-th column: Q[:,k] = A[:,k] / ||A[:,k]||. */
      const DATA_TYPE rkk = SQRT_FUN(nrm);
      R_[k][k] = rkk;

      for (i = 0; i < _PB_M; i++)
        Q_[i][k] = A_[i][k] / rkk;

      /* 3. Compute R[k][j] = Q[:,k]^T * A[:,j] for j > k.

         We first zero-initialize the relevant part of row k of R, then
         accumulate the dot-products in a row-oriented fashion:

           for i
             qik = Q[i][k]
             for j = k+1..N-1
               R[k][j] += qik * A[i][j];

         For each fixed (k,j), the accumulation over i happens in the
         same order as in the original code, so floating-point results
         are identical up to the usual IEEE round-off. */
      for (j = k + 1; j < _PB_N; j++)
        R_[k][j] = SCALAR_VAL(0.0);

      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE qik = Q_[i][k];
        DATA_TYPE * __restrict__ Ai = A_[i]; /* row i of A */
        for (j = k + 1; j < _PB_N; j++)
          R_[k][j] += qik * Ai[j];
      }

      /* 4. Update trailing columns of A:

           A[:,j] = A[:,j] - Q[:,k] * R[k][j],  for j > k.

         Again, we use a row-oriented traversal for better memory
         locality: for each row i, update all columns j>k.  Each
         A[i][j] is updated exactly once with the same expression as in
         the original code; the reordering of independent updates does
         not change the result. */
      for (i = 0; i < _PB_M; i++)
      {
        const DATA_TYPE qik = Q_[i][k];
        DATA_TYPE * __restrict__ Ai = A_[i];
        for (j = k + 1; j < _PB_N; j++)
          Ai[j] -= qik * R_[k][j];
      }
    }
#pragma endscop

}


