/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* QR Decomposition with Modified Gram Schmidt:
   http://www.inf.ethz.ch/personal/gander/

   Optimized version:
   - Uses temporary 1D buffers to improve data locality.
   - Traverses A row-wise (i outer, j inner) for the expensive
     parts of the computation to match C row-major layout.
   - Avoids repeated strided loads of the same column from A/Q.
   - Keeps arithmetic identical up to reordering of associative
     operations (floating-point round-off may differ slightly).
*/
static
void kernel_gramschmidt [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
			DATA_TYPE POLYBENCH_2D(R,N,N,n,n),
			DATA_TYPE POLYBENCH_2D(Q,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE nrm;

  /* Create local restrict-qualified aliases for better
     optimization and clearer indexing semantics.  The
     underlying storage is the same as for A, R, and Q. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*)[n]) A;
  DATA_TYPE (*restrict R_)[n] = (DATA_TYPE (*)[n]) R;
  DATA_TYPE (*restrict Q_)[n] = (DATA_TYPE (*)[n]) Q;

  /* Temporary buffers:
     - q_tmp: holds the current column of Q contiguously.
              During norm computation it temporarily holds
              the corresponding column of A.
     - r_tmp: holds the current row of R contiguously
              (entries R[k][j] for j > k).
     Their sizes are proportional to M and N respectively
     and add only O(M + N) auxiliary memory. */
  DATA_TYPE q_tmp[m];
  DATA_TYPE r_tmp[n];

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      /* 1. Compute the 2-norm of the k-th column of A.
             nrm = sum_i A[i][k]^2

         While doing so, store A's k-th column into q_tmp[].
         This avoids having to reload the same column with a
         strided access pattern in a later loop. */
      nrm = SCALAR_VAL(0.0);
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE A_ik = A_[i][k];
          q_tmp[i] = A_ik;            /* Temporarily store column A[:,k] */
          nrm += A_ik * A_ik;
        }

      /* 2. Normalize k-th column to produce k-th column of Q.
            R[k][k] = sqrt(nrm);
            Q[i][k] = A[i][k] / R[k][k];
         We also overwrite q_tmp[] to hold Q[:,k] contiguously. */
      DATA_TYPE Rkk = SQRT_FUN(nrm);
      R_[k][k] = Rkk;

      /* Replace multiple divisions by a single reciprocal. */
      DATA_TYPE inv_Rkk = SCALAR_VAL(1.0) / Rkk;

      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE qik = q_tmp[i] * inv_Rkk; /* qik = A[i][k] / Rkk */
          Q_[i][k] = qik;                     /* Store in original Q */
          q_tmp[i] = qik;                     /* Store contiguously */
        }

      /* 3. Build the rest of the k-th row of R and update
            the trailing submatrix of A.

         Original algorithm (column-oriented, poor locality):

           for (j = k+1; j < N; j++) {
             R[k][j] = 0;
             for (i = 0; i < M; i++)
               R[k][j] += Q[i][k] * A[i][j];
             for (i = 0; i < M; i++)
               A[i][j] -= Q[i][k] * R[k][j];
           }

         Optimized algorithm (row-oriented, better locality):

           a) Initialize r_tmp[j] = 0 for j > k.
           b) For each row i, walk across columns j > k:
                r_tmp[j] += q_tmp[i] * A[i][j];
              This computes all R[k][j] in a row-major
              traversal of A.
           c) Copy r_tmp[j] into R[k][j].
           d) For each row i, update A[i][j] in the same
              row-major fashion:
                A[i][j] -= q_tmp[i] * r_tmp[j];

         The mathematical result is the same up to floating-
         point round-off; only the order of summation changes. */

      /* a) Initialize needed part of r_tmp. */
      for (j = k + 1; j < _PB_N; j++)
        r_tmp[j] = SCALAR_VAL(0.0);

      /* b) Compute R[k][j] using row-major traversal of A. */
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE qik = q_tmp[i];

          /* For fixed i, A_[i][j] is contiguous in memory as j
             varies, which matches C's row-major layout and
             significantly improves cache utilization. */
          for (j = k + 1; j < _PB_N; j++)
            {
              r_tmp[j] += qik * A_[i][j];
            }
        }

      /* c) Store the completed k-th row of R. */
      for (j = k + 1; j < _PB_N; j++)
        {
          R_[k][j] = r_tmp[j];
        }

      /* d) Update the trailing submatrix of A.  Again we use
            row-major traversal: i outer, j inner. */
      for (i = 0; i < _PB_M; i++)
        {
          DATA_TYPE qik = q_tmp[i];

          for (j = k + 1; j < _PB_N; j++)
            {
              A_[i][j] -= qik * r_tmp[j];
            }
        }
    }
#pragma endscop

}


